package com.modelforge.nativeeditor

import org.junit.Assert.*
import org.junit.Test
import java.io.File

/** Exercises real compressed GLBs generated by tools/generate_forge_basics.py. */
class ForgeAssetLibraryTest {
    private fun pack():ForgeAssetPack = ForgeAssetPack.open(
        File("src/main/assets/packs/forge-basics.mfpack")
    )

    @Test fun catalogIsCompressedAndOnlyManifestLoadsForListing() {
        val pack=pack()
        assertEquals("forge-basics-cc0",pack.packId)
        assertEquals(18,pack.entries.size)
        assertTrue(pack.file.length() < 250_000)
        assertTrue(pack.entries.map{it.category}.distinct().size>=3)
        assertTrue(pack.entries.all {it.license=="CC0-1.0" &&
            it.source=="original procedural mesh"})
        assertTrue(pack.entries.map{it.file}.distinct().size==18)
        assertEquals(18,pack.entries.map{it.sha256}.distinct().size)
    }

    @Test fun eachSelectedCompressedGlbDecodesIntoRealNormalsAndVertices() {
        val pack=pack()
        for(item in pack.entries) {
            val glb=pack.selectedGlb(item.id)
            assertEquals(item.bytes,glb.size)
            val mesh=LibraryGlbMesh.read(glb)
            assertEquals(item.title,mesh.name)
            assertEquals(4,mesh.color.size)
            assertTrue(mesh.vertices.size>=216)
            assertEquals(0,mesh.vertices.size%18)
            assertTrue(mesh.vertices.all(Float::isFinite))
        }
    }

    @Test fun compressedPartCanBeInsertedIntoBlankAssemblyThenReopened() {
        val pack=pack()
        val selected=pack.entries.first{it.id=="aero_fin"}
        val mesh=LibraryGlbMesh.read(pack.selectedGlb(selected.id))
        val editor=GlbWorkshop.blank()
        assertTrue(editor.parts().isEmpty())
        val inserted=editor.addPart(selected.title,mesh.vertices,mesh.color)
        assertEquals(1,editor.parts().size)
        val reopened=GlbWorkshop.open(inserted)
        assertEquals("Aero fin",reopened.parts()[0].label)
        assertEquals(1,reopened.parts().size)
        assertTrue(editor.undo()!=null && editor.parts().isEmpty())
        assertTrue(editor.redo()!=null && editor.parts().size==1)
    }

    @Test fun unknownObjectIsNeverDecompressed() {
        val catalog=pack()
        try {
            catalog.selectedGlb("../not-in-library.glb")
            fail("Expected unknown asset rejection")
        } catch(_:IllegalArgumentException) {}
    }
}
